<?php
if (!defined("SUAVE_RAIZ")) { http_response_code(404); exit; } use Suave\Interfaz as V;use Suave\Numeros as N;
$id=(int)($_GET['id']??$_POST['id']??0);$delivery=(new Suave\Entregas($db))->get($id);
if(isset($_GET['editar'])||($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='entrega_guardar')){require __DIR__.'/capturar.php';return;}
$historical=false;$selected=(int)($_GET['version']??$delivery['version_actual']);
if($selected!==(int)$delivery['version_actual']){$version=$db->one('SELECT * FROM entrega_versiones WHERE entrega_id=? AND numero=?',[$id,$selected]);if(!$version)throw new Suave\ErrorUsuario('La versión de entrega no existe.');$historical=true;$delivery=array_replace($delivery,$version);$delivery['id']=$id;$delivery['version_id']=(int)$version['id'];$delivery['datos']=Suave\Datos::decode($version['datos_json']);$delivery['lineas']=$db->all('SELECT * FROM entrega_lineas WHERE version_id=? ORDER BY posicion',[$version['id']]);}
$return=($_GET['volver']??'')==='conciliacion'?'conciliacion':'entregas';
?>
<div class="page-heading"><div><h1>Entrega <?=V::h($delivery['referencia'])?></h1><p>Versión <?=$selected?> · <?=V::h($delivery['sucursal_codigo']?:'Sucursal sin indicar')?> · <?=V::date($delivery['fecha'])?></p></div><?=V::badge($delivery['estado'])?></div>
<?php if($historical):?><div class="notice">Estás consultando una versión histórica. <?=$w->link('Ver versión vigente','ver_entrega',['id'=>$id],'text-link')?></div><?php endif?>
<div class="action-row spread"><?=$w->link('← Volver a la lista',$return)?><?php if(!$historical):?><?=$w->link($delivery['estado']==='Borrador'?'Continuar borrador':'Editar entrega',$delivery['estado']==='Borrador'?'capturar':'ver_entrega',['id'=>$id,'editar'=>$delivery['estado']==='Registrada'?1:null],'button primary')?><?php endif?></div>
<div class="detail-grid"><section class="soft-panel"><h2>Datos de la nota</h2><dl><dt>Sucursal</dt><dd><?=V::h(($delivery['sucursal_codigo']??'').' · '.($delivery['sucursal_nombre']??'Sin indicar'))?></dd><dt>Fecha de entrega</dt><dd><?=V::date($delivery['fecha'])?></dd><dt>Folio del papel</dt><dd><?=V::h($delivery['folio']?:'Sin folio')?></dd><dt>Respaldo físico</dt><dd><?=V::h(V::backing($delivery['respaldo']))?></dd></dl></section><section class="soft-panel"><h2>Importe de la entrega</h2><div class="large-amount"><?=N::currency((int)$delivery['total_centavos'])?> <small>MXN</small></div><p><?=$delivery['estado']==='Borrador'?'Este borrador no participa en las sumas ni en la conciliación.':'Importe calculado con los renglones de esta versión.'?></p></section></div>
<div class="table-wrap"><table><thead><tr><th>Producto histórico</th><th>Cantidad</th><th>Precio</th><th>Importe</th></tr></thead><tbody><?php foreach($delivery['lineas'] as $line):?><tr><td><?=V::h($line['producto_nombre']?:'Sin producto')?></td><td><?=$line['cantidad_milesimas']===null?'Pendiente':V::h(rtrim(rtrim(N::input((int)$line['cantidad_milesimas'],3),'0'),'.'))?></td><td><?=$line['precio_centavos']===null?'Pendiente':N::currency((int)$line['precio_centavos'])?></td><td><?=$line['importe_centavos']===null?'Pendiente':N::currency((int)$line['importe_centavos'])?></td></tr><?php endforeach?><?php if(!$delivery['lineas']):?><tr><td colspan="4" class="empty-cell">Borrador sin renglones completos.</td></tr><?php endif?></tbody></table></div>
<section class="section-block"><h2>Copias y respaldos</h2><?php $copies=array_filter($delivery['archivos'],fn($f)=>(int)$f['version_numero']<=$selected);if(!$copies):?><p class="hint">No hay copia digital adjunta. El estado del respaldo físico se indica en la nota.</p><?php else:?><ul class="file-list"><?php foreach($copies as $file):?><li><?=$w->link($file['nombre'],'archivo',['id'=>$file['id']],'text-link')?> <small>· <?=number_format($file['bytes']/1024,1)?> KB · adjunta en v<?=$file['version_numero']?></small></li><?php endforeach?></ul><?php endif?>
<?php if(!$historical && $period['estado']!=='Revisado'):?><form method="post" enctype="multipart/form-data" class="inline-upload"><?=V::protect('entrega_adjuntar')?><?=V::hidden('id',$id)?><?=V::hidden('mes',$delivery['mes'])?><label class="field"><span>Agregar otra copia a esta entrega</span><input type="file" name="copia" accept=".pdf,.png,.jpg,.jpeg" required></label><button class="button" type="submit">Adjuntar copia</button></form><?php endif?></section>
<section class="section-block"><h2>Historial de la entrega</h2><div class="table-wrap"><table><thead><tr><th>Versión</th><th>Guardada</th><th>Estado</th><th>Importe</th><th>Motivo</th><th>Consulta</th></tr></thead><tbody><?php foreach($db->all('SELECT numero,estado,total_centavos,motivo,creado_en FROM entrega_versiones WHERE entrega_id=? ORDER BY numero DESC',[$id]) as $version):?><tr><td>v<?=$version['numero']?></td><td><?=V::h($version['creado_en'])?></td><td><?=V::badge($version['estado'])?></td><td><?=N::currency((int)$version['total_centavos'])?></td><td><?=V::h($version['motivo'])?></td><td><?=$w->link('Consultar','ver_entrega',['id'=>$id,'version'=>$version['numero']],'text-link')?></td></tr><?php endforeach?></tbody></table></div></section>
